        "½": {"item": "ds-body", "props": {"title": "Dr. Aiko Tanabe", "kicker": "Membranes · Shelter B", "angle": 1.0, "color": "#5a8a9a", "skin": "#f0d4b8", "hair": "#1a1410", "faceless": true, "text": "Aiko ran the membrane lab. Her badge is still clipped to her coat, and you look at the photo on it instead of at her, because where her face was there is only something smooth and pale."}},
        "¾": {"item": "ds-body", "props": {"title": "Luis Ferreira", "kicker": "Mycology · Shelter B", "angle": 2.0, "color": "#6a6a3a", "skin": "#a8744a", "hair": "#1a1410", "faceless": true, "text": "Luis is curled on his side as if he was asleep when it came. He has no face now. His hands are folded under where it was."}},
        "¿": {"item": "ds-body", "props": {"title": "Grace Obi", "kicker": "Oncology · Shelter B", "angle": -0.6, "color": "#5a7a8a", "skin": "#7a4a30", "hair": "#140c0a", "faceless": true, "text": "Grace. A nurse, from the infusion chairs. Her hands are up over where her face was. They didn’t help."}},
        "À": {"item": "ds-body", "props": {"title": "Tom Whitlock", "kicker": "Discovery Center · Shelter B", "angle": 0.4, "color": "#2f5a68", "skin": "#e0c0a0", "hair": "#8a5a2a", "faceless": true, "text": "Tom gave the school tours. His lanyard says ASK ME ABOUT SYNTHIDS! You don’t look at the rest of him for long."}},
        "Á": {"item": "ds-body", "props": {"title": "Priyanka Rao", "kicker": "Postdoc · Shelter B", "angle": 2.6, "color": "#6a3a4a", "skin": "#a8744a", "hair": "#140c0a", "faceless": true, "text": "Priyanka. A clipboard in her lap: fourteen names, ticked off one by one as they arrived. Hers is the last tick. Her face is gone, lifted away so neatly that her glasses are still on the floor beside her, folded."}},
        "Â": {"item": "ds-body", "props": {"title": "Ben Kowalczyk", "kicker": "Lab technician · Shelter B", "angle": -1.4, "color": "#3a4a5a", "skin": "#f0d4b8", "hair": "#6a4a2a", "faceless": true, "text": "Ben made it back to the door. The scratches on the inside of the blast door are his. Whatever took his face took it there."}},
        "Ã": {"item": "ds-body", "props": {"title": "Marta Szabo", "kicker": "Administration · Shelter B", "angle": 1.8, "color": "#5a4a6a", "skin": "#e0c0a0", "hair": "#2a1e16", "faceless": true, "text": "Marta. A cardigan, a lanyard, a smooth pale nothing where a face should be."}},
        "Ä": {"item": "ds-body", "props": {"title": "Jonah Reyes", "kicker": "Dispatch · Shelter B", "angle": 0.0, "color": "#4a5a3a", "skin": "#8a5a3a", "hair": "#140c0a", "faceless": true, "text": "Jonah ran the sample lift. He is lying face up. That is the wrong way to put it, and there isn’t a right one."}},
        "Å": {"item": "ds-body", "props": {"title": "Dr. Ezra Lindqvist", "kicker": "Air Garden · Shelter B", "angle": -2.4, "color": "#3a6a4a", "skin": "#f0d4b8", "hair": "#c8a060", "faceless": true, "text": "Ezra looked after the frond beds. There is soil under his fingernails, and nothing at all where his face was."}},
        "Æ": {"item": "ds-body", "props": {"title": "Nadia Haddad", "kicker": "Oncology · Shelter B", "angle": 0.9, "color": "#5a7a8a", "skin": "#c49a7a", "hair": "#2a1e16", "face": true, "text": "Nadia Haddad. Oncology. Eyes closed, as if asleep. A single pale strand lies across her cheek, resting there.\n\nWaiting.", "after": "Nadia’s face is gone now. You watched it go."}},
        "Ç": {"item": "ds-body", "props": {"title": "Sam Okoye", "kicker": "Intern · Shelter B", "angle": -2.0, "color": "#3a4a6a", "skin": "#7a4a30", "hair": "#140c0a", "face": true, "text": "Sam Okoye. Intern. Eyes closed, as if asleep. A single pale strand lies across his cheek, resting there.\n\nWaiting.", "after": "Sam’s face is gone now. You watched it go."}},
